def select_action(self):
    if self.rng.random() < self.epsilon:
        return self.rng.integers(self.n_arms)
    return int(np.argmax(self.q))

def update(self, action, reward):
    self.n[action] += 1
    self.q[action] += (reward - self.q[action]) / self.n[action]

